class gsl_combination:
    def __init__(self, n, k):
        self.n = n
        self.k = k
        self.comb = gsl.gsl_combination_alloc(n, k)
        if not self.comb:
            raise Exception("Memory allocation failed")
        gsl.gsl_combination_init_first(self.comb)

    def get_combination(self):
        result = [0] * self.k
        for i in range(self.k):
            result[i] = ctypes.c_int.from_address(ctypes.addressof(self.comb.data.contents) + i * ctypes.sizeof(ctypes.c_int)).value
        return result

    def __del__(self):
        gsl.gsl_combination_free(self.comb)

def create_first_combination(n, k):
    try:
        comb = gsl_combination(n, k)
        return comb.get_combination()
    except Exception as e:
        print(e)
        return None

