class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data_type = ctypes.c_double * (self.rows * self.cols)
        self.data = self.data_type(*sum(self.matrix, []))

