import ctypes
class gsl_matrix(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)),
                ('size1', ctypes.c_size_t),
                ('tda', ctypes.c_size_t)]
class gsl_vector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)),
                ('size', ctypes.c_size_t)]
def numpy_to_gsl_matrix(np_array):
    return gsl_matrix(data=np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), size1=np_array.shape[0], tda=np_array.strides[0]//np_array.itemsize)
def numpy_to_gsl_vector(np_array):
