hesstri_decomp.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector)]
def hesstri(A, B, U=None, V=None, work=None):
    A_gsl = numpy_to_gsl_matrix(A)
    B_gsl = numpy_to_gsl_matrix(B)
    if U is None:
        U = np.eye(A.shape[0], dtype=np.double)
    if V is None:
        V = np.eye(A.shape[0], dtype=np.double)
    if work is None:
        work = np.zeros(A.shape[0]-1, dtype=np.double)
    U_gsl = numpy_to_gsl_matrix(U)
    V_gsl = numpy_to_gsl_matrix(V)
    work_gsl = numpy_to_gsl_vector(work)
    hesstri_decomp(ctypes.byref(A_gsl), ctypes.byref(B_gsl), ctypes.byref(U_gsl), ctypes.byref(V_gsl), ctypes.byref(work_gsl))
    return A, B, U, V

