class RingBuf:
    def __init__(self, size):
        self.size = size
        self.ringbuf = gsl.gsl_ring_buffer_alloc(size)
        if not self.ringbuf:
            raise Exception("Failed to allocate ring buffer")

    def insert_into_ringbuf(self, values):
        for value in values:
            status = gsl.gsl_ring_buffer_insert(self.ringbuf, ctypes.c_double(value))
            if status != 0:
                raise Exception("Failed to insert into ring buffer")

