def compute_inverse_hyperbolic_functions(x):
    if x < 1:
        raise ValueError("Input must be greater than or equal to 1 for acosh")
    elif x == float('inf'):
        return (float('inf'), float('inf'), float('nan'))
    elif x == float('-inf'):
        return (-float('inf'), float('-inf'), float('nan'))
    else:
        gsl_acosh = gsl.acosh
        gsl_asinh = gsl.asinh
        gsl_atanh = gsl.atanh
        gsl_acosh.argtypes = [ctypes.c_double]
        gsl_acosh.restype = ctypes.c_double
        gsl_asinh.argtypes = [ctypes.c_double]
        gsl_asinh.restype = ctypes.c_double
        gsl_atanh.argtypes = [ctypes.c_double]
        gsl_atanh.restype = ctypes.c_double
        acosh_result = gsl_acosh(x)
        asinh_result = gsl_asinh(x)
        atanh_result = gsl_atanh(x)
        return (acosh_result, asinh_result, atanh_result)

