        self.A_indices = A_indices
        self.A_indptr = A_indptr

    def to_ctypes(self):
        return (ctypes.c_double * len(self.A_data))(*self.A_data), (ctypes.c_int * len(self.A_indices))(*self.A_indices), (ctypes.c_int * len(self.A_indptr))(*self.A_indptr)

def solve_gmres(A_data, A_indices, A_indptr, b, n, tol):
    b_ctypes = GSLVector(b).to_ctypes()
    x = (ctypes.c_double * n)()

    A_data_c, A_indices_c, A_indptr_c = GSLSparseMatrix(A_data, A_indices, A_indptr).to_ctypes()

    gsl.gsl_vector_set_basis.restype = ctypes.POINTER(gslcblas.GSL_vector)
    x_ptr = gsl.gsl_vector_set_basis(None, 0)

    solve_gmres_func = gsl.gsl_linalg_gmres_solve
    solve_gmres_func.argtypes = [ctypes.c_int, ctypes.c_int, A_data_c.__class__, A_indices_c.__class__, A_indptr_c.__class__, b_ctypes.__class__, x_ptr]
    solve_gmres_func.restype = ctypes.c_int

    status = solve_gmres_func(n, n, A_data_c, A_indices_c, A_indptr_c, b_ctypes, x_ptr)

