ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLVector:
    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.vector = gsl.gsl_vector_alloc(self.n)
        for i in range(self.n):
            gsl.gsl_vector_set(self.vector, i, data[i])

    def get_data(self):
        return [gsl.gsl_vector_get(self.vector, i) for i in range(self.n)]

    def __del__(self):
        gsl.gsl_vector_free(self.vector)

class GSLSparseMatrix:
    def __init__(self, data, indices, indptr):
        self.data = data
        self.indices = indices
        self.indptr = indptr
        self.n = len(indptr) - 1
        self.matrix = gsl.gsl_spmatrix_alloc(self.n, self.n)
        for i in range(len(data)):
            gsl.gsl_spmatrix_set(self.matrix, indptr[i], indices[i], data[i])

    def __del__(self):
        gsl.gsl_spmatrix_free(self.matrix)

def solve_gmres(A_data, A_indices, A_indptr, b, n, tol):
    A = GSLSparseMatrix(A_data, A_indices, A_indptr)
    b_vec = GSLVector(b)
    x_vec = gsl.gsl_vector_alloc(n)
    gsl.gsl_spmatrix_fprintf(gsl.stdio.STDOUT, A.matrix, "%g")
    gsl.gsl_vector_fprintf(gsl.stdio.STDOUT, b_vec.vector, "%g")
    result = gsl.gsl_linalg_gmres(A.matrix, x_vec.vector, b_vec.vector, tol)
    if result == 0:
        return [x_vec.get_data()]
    else:
        raise Exception(f"GSL GMRES solver failed with error code {result}")

