def is_positive_definite(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    if rows != cols:
        return False
    gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix.data[i*cols + j] = matrix[i][j]

    positive_definite = gsl.gsl_linalg_cholesky_decomp(gsl_matrix) == 0
    gsl.gsl_matrix_free(gsl_matrix)
    return positive_definite

def cholesky_decomp(matrix):
    if not is_positive_definite(matrix):
        raise ValueError(\"Matrix must be positive definite\")

    rows = len(matrix)
    cols = len(matrix[0])
    l_matrix = [[matrix[i][j] if i >= j else 0 for j in range(cols)] for i in range(rows)]
    gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix.data[i*cols + j] = matrix[i][j]

    gsl.gsl_linalg_cholesky_decomp(gsl_matrix)
    for i in range(rows):
        for j in range(i+1, cols):
            l_matrix[i][j] = 0

    for i in range(rows):
        for j in range(cols):
            matrix[i][j] = l_matrix[i][j]

    return matrix

