class GSLVector(ctypes.Structure):
    _fields_ = ["size", "stride", ("data", ctypes.POINTER(ctypes.c_double))]

def find_max_in_vector(input_list):
    if not input_list:
        raise ValueError("Input list cannot be empty")
    vector_data = (ctypes.c_double * len(input_list))(*input_list)
    gsl_vector = GSLVector(len(input_list), 1, ctypes.cast(vector_data, ctypes.POINTER(ctypes.c_double)))
    max_value = gsl.gsl_vector_max(gsl_vector)
    return float(max_value)

