class GslRstatQuantileWorkspace:
    def __init__(self, size: int):
        self.workspace = gsl.gsl_rstat_quantile_alloc(size)
        if not self.workspace:
            raise MemoryError("Failed to allocate GSL quantile workspace")

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self.workspace)

    def add(self, value: float):
        gsl.gsl_rstat_quantile_add(self.workspace, value)

    def get_quantile(self, p: float) -> float:
        return gsl.gsl_rstat_quantile_get(self.workspace, p)

    def free(self):
        gsl.gsl_rstat_quantile_free(self.workspace)

def compute_quantile(p: float, values: List[float]) -> float:
    if not (0 <= p <= 1):
        raise ValueError("Quantile p must be between 0 and 1")

    with GslRstatQuantileWorkspace(len(values)) as workspace:
        for value in values:
            workspace.add(value)
        return workspace.get_quantile(p)

